def beat_07(v):
    base = 150

    def g(x, cx, s=85.0):
        return math.exp(-((x - cx) ** 2) / (2.0 * s * s))

    def curve(cx, h):
        pts = [(-300, base)]
        for x in range(-300, 301, 12):
            pts.append((x, base - h * g(x, cx)))
        pts.append((300, base))
        return pts

    ax = v.ease(0.0, 0.6)
    # graph axes drawing themselves
    v.line(-320, base, 330, base, width=8, color="dark", progress=ax)
    v.line(-320, base, -320, -210, width=8, color="dark", progress=v.ease(0.15, 0.5))
    for i in range(1, 6):
        tx = -320 + i * 110
        v.line(tx, base, tx, base + 14, width=5, color="dark", alpha=int(255 * ax))

    wob = v.wave(freq=3.0, amp=10.0) * max(0.0, 1.0 - v.lt / 3.0)
    hb = 250 * v.spring(0.5, 0.6) + wob * v.ease(0.5, 0.3)
    sp = v.spring(1.0, 0.6)
    hp = 245 * sp - wob * sp
    cb = -12
    cp = 180 - 165 * v.ease(1.3, 1.0)

    if hb > 2:
        v.poly(curve(cb, hb), color="blue_tear", alpha=140)
    if hp > 2:
        v.poly(curve(cp, hp), color="pink_organ", alpha=140)
    if hb > 2 and hp > 2:
        ov = [(-300, base)]
        for x in range(-300, 301, 12):
            ov.append((x, base - min(hb * g(x, cb), hp * g(x, cp))))
        ov.append((300, base))
        v.poly(ov, color="purple", alpha=int(210 * v.ease(1.5, 0.8)))

    if hb > 2:
        v.circle(cb, base - hb, 10, color="blue_tear")
        v.label_pill(cb - 140, base - hb + 20, text="PRIA", bg="blue_tear", fg="white", size=26, pointer=False, delay=0.7)
    if hp > 2:
        v.circle(cp, base - hp, 10, color="pink_organ")
        v.label_pill(cp + 150, base - hp + 20, text="WANITA", bg="pink_organ", fg="white", size=26, pointer=False, delay=1.2)
    v.label_pill(0, base + 55, text="HAMPIR SAMA", bg="purple", fg="white", size=28, pointer=False, delay=2.1)
